.instructors-grid { display: grid; gap: 20px; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); }
.instructor-card { padding: 14px; border: 1px solid var(--line); border-radius: 14px; background: var(--bg-elev); }
.instructor-card img { border-radius: 10px; height: 220px; width: 100%; object-fit: cover; }
.instructor-card h4 { margin: 12px 0 4px; font-family: Oswald, sans-serif; text-transform: uppercase; }

.faq-item { border-bottom: 1px solid var(--line); }
.faq-btn {
  width: 100%;
