footer { border-top: 1px solid #252525; padding: 34px 0; margin-top: 58px; }
.footer-row { display: flex; justify-content: space-between; gap: 20px; flex-wrap: wrap; align-items: center; }
.small { font-size: .86rem; color: #c0c0c0; }
